# -*- coding: utf-8 -*-
import json
import os
import re

path = r"C:\Users\win\.codex\sessions\2026\07\30\rollout-2026-07-30T20-06-50-019fb2eb-8ec5-7cc3-9421-c99d5179701c.jsonl"
print("size", os.path.getsize(path))

cmds = []
cwd_hits = []
file_paths = []
git_lines = []
push_mentions = []
commit_mentions = []
types = {}
n = 0

commit_re = re.compile(r"git\s+commit", re.I)
push_re = re.compile(r"git\s+push", re.I)
cwd_re = re.compile(
    r"(?:cwd|working_directory|workdir|current_working_directory)[\"']?\s*[:=]\s*[\"']([^\"']+)",
    re.I,
)
path_re = re.compile(r"[A-Za-z]:\\Users\\[^\"'\\]+\\Desktop\\alpha[^\"'\\]*", re.I)
path_re2 = re.compile(r"/Users/[^\"'\\]+/Desktop/alpha[^\"'\\]*")

with open(path, "r", encoding="utf-8", errors="replace") as f:
    for line in f:
        n += 1
        try:
            o = json.loads(line)
        except Exception:
            continue
        t = o.get("type") or ""
        types[t] = types.get(t, 0) + 1
        s = json.dumps(o, ensure_ascii=False)

        for x in cwd_re.findall(s):
            cwd_hits.append(x)
        for x in path_re.findall(s):
            file_paths.append(x)
        for x in path_re2.findall(s):
            file_paths.append(x)

        if commit_re.search(s):
            commit_mentions.append((n, t, s[:600]))
        if push_re.search(s):
            push_mentions.append((n, t, s[:600]))
        if "git " in s.lower():
            if any(k in s.lower() for k in ["push", "commit", "status", "add ", "fetch", "worktree", "branch"]):
                git_lines.append((n, t, s[:500]))

        item = o.get("payload") if isinstance(o.get("payload"), dict) else None
        if isinstance(item, dict):
            if "command" in item:
                cmds.append(str(item.get("command"))[:500])
            if isinstance(item.get("item"), dict):
                it = item["item"]
                if it.get("command"):
                    cmds.append(str(it.get("command"))[:500])

        # common rollout shapes
        if isinstance(o.get("item"), dict):
            it = o["item"]
            if it.get("command"):
                cmds.append(str(it.get("command"))[:500])
            changes = it.get("changes") or it.get("files") or []
            if isinstance(changes, list):
                for ch in changes[:20]:
                    if isinstance(ch, dict):
                        p = ch.get("path") or ch.get("filename") or ""
                        if p:
                            file_paths.append(str(p))
                    elif isinstance(ch, str):
                        file_paths.append(ch)

print("lines", n)
print("types top:")
for k, v in sorted(types.items(), key=lambda kv: -kv[1])[:30]:
    print(f"  {k}: {v}")

print("\nunique cwds:")
for x in sorted(set(cwd_hits)):
    print(" ", x)

print("\npath samples:")
for x in sorted(set(file_paths))[:80]:
    print(" ", x)

print("\ncommands:", len(cmds))
interesting = []
for c in cmds:
    cl = c.lower()
    if any(k in cl for k in ["git", "push", "commit", "pytest", "python", "gh ", "origin"]):
        interesting.append(c)
print("interesting:", len(interesting))
for c in interesting[:120]:
    print("CMD:", c.replace("\n", " ")[:350])

print("\ncommit mentions:", len(commit_mentions))
for ln, t, s in commit_mentions[:20]:
    print(f"COMMIT@{ln} {t}: {s[:350]}")

print("\npush mentions:", len(push_mentions))
for ln, t, s in push_mentions[:20]:
    print(f"PUSH@{ln} {t}: {s[:350]}")

print("\ngit lines:", len(git_lines))
for ln, t, s in git_lines[:40]:
    print(f"GIT@{ln} {t}: {s[:300]}")

